edits.replacement:
#root .ocwin .haulit[data-r="gold"]{ border-bottom-color:var(--r-gold) !important; }
/* v28.xx (cw-endcard-hero): the critic, second pass on the Extracted and KIA cards (2 of 5): "no hero line, the HUD still bleeds through the scrim,
   the feedback chip is a third competing control with an amber plus". The haul total is the hero now: 56px, bone, no tracking, 16px above and 24px
   below. The scrim is near solid (.94) so the HUD cannot read through. The feedback prompt is a quiet 16px text link in tx-2 with no box and no amber. */
#root .outcome{ background:rgba(6,7,8,.94); }
#root .haultot{ font-size:56px; line-height:1.05; letter-spacing:0; color:var(--tx-1); text-transform:none; margin:16px 0 24px; }
#root .ocwin .fbhead{ background:transparent; border:0; color:var(--tx-2); font-size:16px; padding:8px 16px; margin-top:16px; }
#root .ocwin .fbhead::after{ color:var(--tx-2); }

check:
{v:'VER',what:'the end card has a 56px hero total, a near-solid scrim and a quiet feedback link (critic: no hero line, HUD bleeds, third control; screens 35 38 77)',
 run:function(){
   var oc=document.getElementById('outcome'), win=oc&&oc.querySelector('.ocwin'), fb=document.getElementById('fbhead'), d, res=null, a;
   if(!oc||!win||!fb) return 'SKIP: no end card here';
   d=document.createElement('div'); d.className='haultot'; win.appendChild(d);
   try{
     if(parseFloat(getComputedStyle(d).fontSize)<56) res='the haul total is '+getComputedStyle(d).fontSize+', not 56px';
   }finally{ win.removeChild(d); }
   if(res) return res;
   a=/rgba?\([^)]*?,\s*([\d.]+)\)/.exec(getComputedStyle(oc).backgroundColor);
   if(!a||parseFloat(a[1])<0.9) return 'the scrim is '+getComputedStyle(oc).backgroundColor+', the HUD reads through';
   if(getComputedStyle(fb).borderTopWidth!=='0px') return 'the feedback prompt still has a box';
   return null;
 }},
